            ["script"] = "local BlockPlayer = require \"actions/BlockPlayer\"\nlocal PlayAudio = require \"actions/PlayAudio\"\nlocal Animate = require \"actions/Animate\"\nlocal MessageBox = require \"actions/MessageBox\"\nlocal Do = require \"actions/Do\"\nlocal Ease = require \"actions/Ease\"\nlocal Wait = require \"actions/Wait\"\nlocal Serial = require \"actions/Serial\"\nlocal Parallel = require \"actions/Parallel\"\nlocal Move = require \"actions/Move\"\nlocal Spawn = require \"actions/Spawn\"\nlocal Repeat = require \"actions/Repeat\"\n\nlocal BasicNPC = require \"object/BasicNPC\"\nlocal NPC = require \"object/NPC\"\n\nreturn function(self)\n    return BlockPlayer {\n        Wait(1),\n        Do(function()\n            self.scene.objectLookup.Cheetah.hidden = false\n            self.scene.objectLookup.Cheetah.movespeed = 30\n            self.scene.player.noIdle = true\n        end),\n        PlayAudio(\"sfx\", \"cheetarun\", 1, true),\n        Parallel {\n            Serial {\n                Move(self.scene.objectLookup.Cheetah, self.scene.objectLookup.CheetahWP, \"run\"),\n                Do(function() self.scene.objectLookup.Cheetah.sprite:setAnimation(\"idleleft\") end),\n                PlayAudio(\"music\", \"sonicscared\", 1, true, true)\n            },\n           Serial {\n                Wait(1),\n                Animate(self.scene.player.sprite, \"shock\"),\n                Wait(1),\n                Do(function()\n                    self.scene.objectLookup.B.hidden = false\n                    self.scene.objectLookup.B.sprite:setAnimation(\"holdsonicscaredright\")\n                    self.scene.objectLookup.B.x = self.scene.player.x - 60\n                    self.scene.objectLookup.B.y = self.scene.player.y - 60\n                end),\n                Parallel {\n                    Ease(self.scene.objectLookup.B, \"x\", self.scene.player.x - 120, 3),\n                    MessageBox{message=\"Sonic: N-No no no!! {p80}How did it get down here?!\"}\n                },\n                Animate(self.scene.player.sprite, \"scaredright\"),\n                MessageBox{message=\"Sally: It must've followed us down here!\"}\n            }\n        },\n        Wait(0.5),\n        Animate(self.scene.player.sprite, \"nicholedown\"),\n        MessageBox{message=\"Sally: Nicole{p60}, reactivate the magnets!\", sfx=\"nicolebeep\"},\n        Do(function()\n            self.scene.magnetsOn = true\n        end),\n        Wait(0.2),\n        Animate(self.scene.objectLookup.Cheetah.sprite, \"hurtleft\"),\n        Spawn(Repeat(\n            Serial {\n                Do(function() self.scene.objectLookup.Cheetah.y = self.scene.objectLookup.Cheetah.y + 2 end),\n                Do(function() self.scene.objectLookup.Cheetah.y  = self.scene.objectLookup.Cheetah.y - 2 end)\n            }\n        )),\n        Spawn(Repeat(\n            Serial {\n                PlayAudio(\"sfx\", \"shocked\", 1, true),\n                Do(function()\n                    if not self.scene.spark then\n                        self.scene.spark = BasicNPC(\n                            self.scene,\n                            {name = \"objects\"},\n                            {name = \"lightning\", x = self.scene.objectLookup.Cheetah.x + 30, y = self.scene.objectLookup.Cheetah.y + 70, width=32, height=32,\n                              properties = {nocollision = true, sprite = \"art/sprites/lightning.png\", align = NPC.ALIGN_BOTLEFT}}\n                        )\n                        self.scene.spark.sprite.sortOrderY = 10000\n                        self.scene:addObject(self.scene.spark)\n                    end\n                    self.scene.spark:run(Serial {\n                        Do(function()\n                            self.scene.spark.hidden = false\n                            self.scene.spark.x = self.scene.objectLookup.Cheetah.x + 30\n                            self.scene.spark.y = self.scene.objectLookup.Cheetah.y + 15\n                        end),\n                        Animate(self.scene.spark.sprite, \"idle\"),\n                        Do(function() self.scene.spark.hidden = true end)\n                    })\n                end),\n                Wait(5)\n            }\n        )),\n\n        Animate(self.scene.player.sprite, \"idleright\"),\n        MessageBox{message=\"Sally: Let's get out of here!\"},\n        Ease(self.scene.objectLookup.B, \"x\", self.scene.player.x - 60, 1),\n        Do(function()\n            self.scene.objectLookup.B.hidden = true\n            self.scene.player.noIdle = false\n            self.scene.player.state = \"idleleft\"\n        end)\n    }\nend"
