f.scene.player, \"x\", function() return self.scene.player.x - 15 end, 1),\n            Ease(self.scene.objectLookup.B, \"x\", function() return self.scene.objectLookup.B.x - 20 end, 1)\n        },\n        MessageBox{message=\"Sonic: Move it along, Nicole!!\", closeAction=Wait(1.5)},\n        Wait(0.5),\n        Animate(self.scene.objectLookup.Cheetah.sprite, \"jitterleft\"),\n        Ease(self.scene.objectLookup.Cheetah, \"x\", function() return self.scene.objectLookup.Cheetah.x - 50 end, 1),\n        Parallel {\n            MessageBox{message=\"Nicole: Override complete.\", sfx=\"nicolebeep\", closeAction=Wait(1)},\n            Serial {\n                PlayAudio(\"sfx\", \"elevatorend\", 1, true),\n                Ease(doorLayer, \"offsety\", 32*-6, 0.8, \"linear\"),\n                Wait(0.2),\n                PlayAudio(\"sfx\", \"elevatorend\", 1, true, false, true),\n                Ease(doorLayer, \"offsety\", 0, 0.8, \"linear\")\n            },\n            Serial {\n                Wait(0.5),\n                Parallel {\n                    Ease(self.scene.player, \"x\", function() return self.scene.player.x - 150 end, 1),\n                    Ease(self.scene.objectLookup.B, \"x\", function() return self.scene.objectLookup.B.x - 100 end, 1)\n                }\n            }\n        },\n    }\nend"
